def solve_magic_sequence(n, fixed={}):
    # Use constraint propagation + backtracking
    # Known solution pattern for length 13: typically looks like [1,2,3,...] style
    # Let's use a smarter approach

    # For a magic sequence of length n:
    # sum(x[i]) = n (total count of all digits)
    # sum(i * x[i]) = n (each x[i] counts i's, so sum of all values = n)

    from pysat.pb import PBEnc
    from pysat.formula import CNF

    # Let's just do backtracking with pruning
    seq = [None] * n

    # Apply fixed values
    for idx, val in fixed.items():
        seq[idx] = val

    def backtrack(pos):
        if pos == n:
            return is_magic_sequence(seq)

        if seq[pos] is not None:
            return backtrack(pos + 1)

        for val in range(n):
            seq[pos] = val
            # Pruning: check partial consistency
            # Count how many times each number appears so far
            counts = {}
            for i in range(n):
                if seq[i] is not None:
                    counts[seq[i]] = counts.get(seq[i], 0) + 1

            valid = True
            for i, cnt in counts.items():
                if seq[i] is not None and seq[i] < cnt:
                    valid = False
                    break

            if valid:
                if backtrack(pos + 1):
                    return True

        seq[pos] = None
        return False

    if backtrack(0):
        return seq
    return None

